<?php

namespace App\Models;

use App\Domain\Sales\Enums\SaleStatus;
use App\Support\Database\ImmutableRecordException;
use Illuminate\Database\Eloquent\Concerns\HasUuids;
use Illuminate\Database\Eloquent\Factories\HasFactory;
use Illuminate\Database\Eloquent\Model;
use Illuminate\Database\Eloquent\Relations\BelongsTo;
use Illuminate\Database\Eloquent\Relations\HasMany;

/**
 * A completed sale. The id is a UUIDv7 generated by the terminal.
 *
 * Preserved forever: never deleted, amounts never change. The only allowed
 * change is completed → voided. Same rules as the `sales_*` triggers.
 */
class Sale extends Model
{
    use HasFactory, HasUuids;

    /** Must match FROZEN_SALE_COLUMNS in the create_sales_tables migration. */
    public const FROZEN_COLUMNS = [
        'store_id', 'device_id', 'cashier_shift_id', 'cashier_id', 'customer_id',
        'receipt_number', 'receipt_sequence', 'occurred_at', 'business_date',
        'customer_name', 'customer_tin', 'customer_address', 'customer_id_number',
        'gross_amount', 'discount_total', 'vatable_sales', 'vat_amount', 'vat_exempt_sales',
        'zero_rated_sales', 'rounding_adjustment', 'grand_total', 'amount_paid', 'change_due',
        'operation_id',
    ];

    protected static function booted(): void
    {
        static::updating(function (self $sale) {
            if ($sale->getOriginal('status') === SaleStatus::Voided) {
                throw ImmutableRecordException::forModel($sale, 'updated after voiding');
            }
            if ($sale->isDirty(self::FROZEN_COLUMNS)) {
                throw ImmutableRecordException::forModel($sale, 'changed (void or return instead)');
            }
        });
        static::deleting(fn (self $sale) => throw ImmutableRecordException::forModel($sale, 'deleted'));
    }

    protected function casts(): array
    {
        return [
            'status' => SaleStatus::class,
            'receipt_sequence' => 'integer',
            'gross_amount' => 'decimal:4',
            'discount_total' => 'decimal:4',
            'vatable_sales' => 'decimal:4',
            'vat_amount' => 'decimal:4',
            'vat_exempt_sales' => 'decimal:4',
            'zero_rated_sales' => 'decimal:4',
            'rounding_adjustment' => 'decimal:4',
            'grand_total' => 'decimal:4',
            'amount_paid' => 'decimal:4',
            'change_due' => 'decimal:4',
            'occurred_at' => 'datetime',
            'business_date' => 'date',
            'synced_at' => 'datetime',
            'voided_at' => 'datetime',
        ];
    }

    public function isVoided(): bool
    {
        return $this->status === SaleStatus::Voided;
    }

    public function store(): BelongsTo
    {
        return $this->belongsTo(Store::class);
    }

    public function device(): BelongsTo
    {
        return $this->belongsTo(Device::class);
    }

    public function shift(): BelongsTo
    {
        return $this->belongsTo(CashierShift::class, 'cashier_shift_id');
    }

    public function cashier(): BelongsTo
    {
        return $this->belongsTo(User::class, 'cashier_id');
    }

    public function customer(): BelongsTo
    {
        return $this->belongsTo(Customer::class);
    }

    public function voider(): BelongsTo
    {
        return $this->belongsTo(User::class, 'voided_by');
    }

    public function items(): HasMany
    {
        return $this->hasMany(SaleItem::class)->orderBy('line_number');
    }

    public function discounts(): HasMany
    {
        return $this->hasMany(SaleDiscount::class);
    }

    public function payments(): HasMany
    {
        return $this->hasMany(Payment::class);
    }

    public function returns(): HasMany
    {
        return $this->hasMany(SaleReturn::class);
    }
}
